module.exports = {"schema":1,"revision":306,"topic_number":56,"legacy_number":62,"topic_id":105,"title":"TEMA 56. NRBQ","pdf_source_name":"TEMA_62_NRBQ.pdf","pdf_sha256":"f81dcff31190f37a7f820eb04a1ffe7a2660eee15dfc1e3cf79ddc62529a9bbf","pdf_pages":92,"pdf_size":4823661,"coverage_total":1955,"exam_relevant":1180,"bank_count":52,"graphic_count":52,"legacy_active_question_fingerprint":"1f5c3f4e472fddade4919daac5cfd3ac","selected_images_count":52,"images_sha_source":"t62_nrbq_data.js, original selected_github mapping","changes":[{"id":2765,"role":1,"source_file":"T62_FIG_01_P019.png","asset_id":152930,"manual_page":"463","correct_index":2,"stem":"Al comparar las dos cruces del grupo de pictogramas antiguos, ¿qué relación entre símbolo, código alfabético y peligro reproduce el sistema del manual?","options":["La cruz de San Andrés identifica corrosivo (C) e irritante (Xi), diferenciados por el código.","La cruz de San Andrés identifica tóxico (T) y nocivo (Xn), diferenciados por el código.","Una misma cruz de San Andrés distingue nocivo (Xn) de irritante (Xi) mediante el código.","La cruz de San Andrés distingue explosivo (E) de comburente (O) mediante el código."],"explanation":"CEIS NRBQ, página impresa 463. La correspondencia correcta es: Una misma cruz de San Andrés distingue nocivo (Xn) de irritante (Xi) mediante el código.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2766,"role":2,"source_file":"T62_FIG_02_P020.png","asset_id":152931,"manual_page":"464","correct_index":0,"stem":"De las seis divisiones de explosivos visibles, ¿qué orden descendente respeta simultáneamente las posiciones intermedias y los extremos establecidos por el manual?","options":["1.1 → 1.5 → 1.2 → 1.3 → 1.6 → 1.4.","1.1 → 1.2 → 1.5 → 1.3 → 1.6 → 1.4.","1.5 → 1.1 → 1.2 → 1.3 → 1.4 → 1.6.","1.1 → 1.5 → 1.3 → 1.2 → 1.6 → 1.4."],"explanation":"CEIS NRBQ, página impresa 464. La correspondencia correcta es: 1.1 → 1.5 → 1.2 → 1.3 → 1.6 → 1.4.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2767,"role":3,"source_file":"T62_FIG_03_P074.png","asset_id":152932,"manual_page":"518","correct_index":3,"stem":"Se observa la evolución de moléculas a través de las capas del traje. ¿Qué asociación entre la secuencia del esquema, el mecanismo y el ensayo de protección resulta correcta?","options":["Absorción inicial, difusión por costuras y rotura exterior caracterizan penetración; el tiempo de paso mide solo el lavado posterior.","Entrada por agujeros, difusión por cierres y detección exterior caracterizan permeación; el tiempo de paso termina al tocar el tejido.","Absorción inicial, filtración macroscópica y salida por una cremallera caracterizan penetración; el tiempo de paso equivale al espesor del traje.","Absorción inicial, difusión molecular y detección interior caracterizan permeación; el tiempo de paso mide el intervalo desde el contacto hasta su detección."],"explanation":"CEIS NRBQ, página impresa 518. La correspondencia correcta es: Absorción inicial, difusión molecular y detección interior caracterizan permeación; el tiempo de paso mide el intervalo desde el contacto hasta su detección.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2768,"role":4,"source_file":"T62_FIG_04_P021.png","asset_id":152933,"manual_page":"465","correct_index":1,"stem":"En las dos etiquetas contiguas, seleccione la combinación que identifica ambas subdivisiones y añade la distinción P1/P2 descrita únicamente para una de ellas.","options":["5.1: peróxidos orgánicos P1; 5.2: comburentes P2, dependiendo ambos del mismo límite de presión.","5.1: materias comburentes; 5.2: peróxidos orgánicos, clasificados P1 o P2 según necesidad de regulación térmica.","5.1: sólidos autorreactivos; 5.2: materias que desprenden gas al mojarse, diferenciadas por temperatura.","5.1: combustibles líquidos; 5.2: gases inflamables, diferenciados por la presión de vapor del recipiente."],"explanation":"CEIS NRBQ, página impresa 465. La correspondencia correcta es: 5.1: materias comburentes; 5.2: peróxidos orgánicos, clasificados P1 o P2 según necesidad de regulación térmica.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2769,"role":5,"source_file":"T62_FIG_05_P060.png","asset_id":152934,"manual_page":"504","correct_index":2,"stem":"Al interpretar el rombo de clase 4 dividido en dos mitades, ¿cuál es la relación correcta entre subdivisión y mecanismo que la distingue de la etiqueta azul?","options":["4.1: desprendimiento de gases inflamables por contacto con el agua, sin aporte externo de energía.","4.3: inflamación espontánea por contacto con el aire, sin aporte externo de energía.","4.2: calentamiento o inflamación espontánea al contacto con el aire, sin aporte externo de energía.","4.2: desprendimiento de gases inflamables al contacto con el agua, sin aporte externo de energía."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: 4.2: calentamiento o inflamación espontánea al contacto con el aire, sin aporte externo de energía.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2770,"role":6,"source_file":"T62_FIG_06_P060.png","asset_id":152935,"manual_page":"504","correct_index":0,"stem":"La reproducción presenta una combinación gráfica antigua potencialmente equívoca. Atendiendo a la cifra impresa, ¿qué clasificación y qué distinción operativa del manual prevalecen?","options":["Clase 5.2: peróxidos orgánicos, diferenciando los que necesitan control de temperatura (P2) de los que no (P1).","Clase 5.1: materias comburentes, diferenciando las que necesitan control de temperatura (P2) de las que no (P1).","Clase 5.2: materias que reaccionan con agua, diferenciando las que precisan inertización (P2) de las que no (P1).","Clase 4.2: materias autoinflamables, diferenciando por presión de transporte los grupos P2 y P1."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: Clase 5.2: peróxidos orgánicos, diferenciando los que necesitan control de temperatura (P2) de los que no (P1).","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2771,"role":7,"source_file":"T62_FIG_07_P060.png","asset_id":152936,"manual_page":"504","correct_index":3,"stem":"Para la etiqueta azul de la figura, ¿qué correspondencia entre clase ADR, mecanismo de peligro y limitación de la mitigación señala el manual?","options":["Clase 4.2: el contacto con aire libera gases inflamables; no emplear espuma, pero sí agua en dilución.","Clase 4.1: el contacto con agua provoca calentamiento espontáneo; emplear agua para diluir el producto.","Clase 5.1: el contacto con aire ocasiona explosión inmediata; utilizar agua para eliminar su poder oxidante.","Clase 4.3: el contacto con agua puede liberar gases inflamables; no emplearla como agente extintor ni para dilución."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: Clase 4.3: el contacto con agua puede liberar gases inflamables; no emplearla como agente extintor ni para dilución.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2772,"role":8,"source_file":"T62_FIG_08_P060.png","asset_id":152937,"manual_page":"504","correct_index":1,"stem":"La etiqueta explosiva remite al conjunto de seis divisiones. ¿Qué pareja identifica, según su orden global de peligrosidad en el manual, los extremos de ese conjunto?","options":["La mayor peligrosidad corresponde a 1.5 y la menor a 1.6, quedando 1.1 por detrás de 1.2.","La mayor peligrosidad corresponde a 1.1 y la menor a 1.4, quedando 1.5 por delante de 1.2.","La mayor peligrosidad corresponde a 1.1 y la menor a 1.6, quedando 1.4 por delante de 1.3.","La mayor peligrosidad corresponde a 1.2 y la menor a 1.4, quedando 1.5 por detrás de 1.3."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: La mayor peligrosidad corresponde a 1.1 y la menor a 1.4, quedando 1.5 por delante de 1.2.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2773,"role":9,"source_file":"T62_FIG_09_P060.png","asset_id":152938,"manual_page":"504","correct_index":2,"stem":"Para la etiqueta verde de gases, indique la combinación que la distingue de las variantes roja y blanca de la misma clase de transporte.","options":["Es la clase 2.1, gas inflamable y no tóxico; la variante roja corresponde al oxidante y la blanca al asfixiante.","Es la clase 2.3, gas tóxico y no inflamable; la variante roja corresponde al asfixiante y la blanca al inflamable.","Es la clase 2.2, gas no inflamable y no tóxico; la variante roja corresponde al inflamable y la blanca con calavera al tóxico.","Es la clase 5.1, gas comburente; la variante roja corresponde al 2.2 y la blanca al 2.1."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: Es la clase 2.2, gas no inflamable y no tóxico; la variante roja corresponde al inflamable y la blanca con calavera al tóxico.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2774,"role":10,"source_file":"T62_FIG_10_P060.png","asset_id":152939,"manual_page":"504","correct_index":0,"stem":"La correspondencia CLP muestra varios símbolos de riesgo sanitario. ¿Qué identificación separa el pictograma de la figura del peligro indicado por la calavera?","options":["La silueta con lesión torácica se vincula a peligros graves para la salud; la calavera señala toxicidad aguda.","La silueta con lesión torácica se vincula a toxicidad aguda; la calavera señala únicamente irritación.","La silueta con lesión torácica se vincula a corrosión cutánea; la calavera señala comburencia.","La silueta con lesión torácica se vincula a gas a presión; la calavera señala peligros ambientales."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: La silueta con lesión torácica se vincula a peligros graves para la salud; la calavera señala toxicidad aguda.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2775,"role":11,"source_file":"T62_FIG_11_P060.png","asset_id":152940,"manual_page":"504","correct_index":3,"stem":"Al distinguir el pictograma CLP representado de la etiqueta de explosivos ADR, ¿cuál es la asociación de riesgos que admite el manual para dicho pictograma?","options":["Exclusivamente los gases de clase ADR 2 que resulten inflamables, sin incluir otras sustancias.","Solo materias de clase ADR 4.3 que desprenden gas al contacto con agua, sin excepciones.","Únicamente residuos corrosivos del sistema antiguo de etiquetas, sin riesgo de detonación.","Explosivos y determinados autorreactivos o peróxidos orgánicos con peligro de explosión, sin limitarse a la clase ADR 1."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: Explosivos y determinados autorreactivos o peróxidos orgánicos con peligro de explosión, sin limitarse a la clase ADR 1.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2776,"role":12,"source_file":"T62_FIG_12_P060.png","asset_id":152941,"manual_page":"504","correct_index":1,"stem":"El símbolo de cilindro pertenece a CLP; ¿qué interpretación evita confundir su función con las variantes de peligrosidad de la clase ADR 2?","options":["Identifica necesariamente gas tóxico, aunque el sistema ADR lo presente con etiqueta verde.","Identifica gas a presión, sin determinar por sí solo si el gas es inflamable o tóxico en la clasificación ADR.","Identifica exclusivamente gas inflamable, aunque el sistema ADR lo presente con etiqueta blanca.","Identifica un oxidante sólido de la clase 5.1, aunque el recipiente sea presurizado."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: Identifica gas a presión, sin determinar por sí solo si el gas es inflamable o tóxico en la clasificación ADR.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2777,"role":13,"source_file":"T62_FIG_13_P060.png","asset_id":152942,"manual_page":"504","correct_index":2,"stem":"Al comparar la llama de la imagen con el signo de llama sobre círculo, ¿qué combinación distingue la naturaleza de ambos peligros y su relación con la clase 5.1?","options":["Llama aislada: carácter comburente; llama sobre círculo: inflamabilidad, correspondiente a materias de clase 4.1.","Llama aislada: gas a presión; llama sobre círculo: toxicidad aguda, correspondiente a materias de clase 6.1.","Llama aislada: inflamabilidad; llama sobre círculo: carácter comburente, correspondiente a materias de clase 5.1.","Llama aislada: corrosión; llama sobre círculo: riesgo ambiental, correspondiente a materias de clase 9."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: Llama aislada: inflamabilidad; llama sobre círculo: carácter comburente, correspondiente a materias de clase 5.1.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2778,"role":14,"source_file":"T62_FIG_14_P060.png","asset_id":152943,"manual_page":"504","correct_index":0,"stem":"El signo de exclamación del esquema CLP se compara con la calavera y la silueta torácica. ¿Qué distinción corresponde al pictograma que aparece?","options":["Se asocia a irritación o nocividad, sin equivaler por sí mismo a toxicidad aguda grave ni al peligro sanitario de la silueta.","Se asocia exclusivamente a toxicidad aguda letal, sin equivaler al riesgo de irritación ni al pictograma de calavera.","Se asocia exclusivamente a efectos crónicos graves, sin equivaler a irritación ni a la silueta torácica.","Se asocia a propiedades comburentes, sin equivaler a inflamabilidad ni a la llama sobre círculo."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: Se asocia a irritación o nocividad, sin equivaler por sí mismo a toxicidad aguda grave ni al peligro sanitario de la silueta.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2779,"role":15,"source_file":"T62_FIG_15_P060.png","asset_id":152944,"manual_page":"504","correct_index":3,"stem":"La señal CLP con árbol y pez se diferencia de las etiquetas de transporte ADR. ¿Qué combinación de símbolo y categoría de riesgo es coherente con la comparación del manual?","options":["Árbol seco y pez muerto: inflamabilidad de líquidos, no una indicación directa de corrosión o gases a presión.","Árbol seco y pez muerto: toxicidad aguda para personas, no una indicación directa de peligro ambiental.","Árbol seco y pez muerto: clase ADR 7 por radiación ionizante, no una indicación directa de impacto ambiental.","Árbol seco y pez muerto: peligro para el medio ambiente, no una indicación directa de inflamabilidad o toxicidad aguda."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: Árbol seco y pez muerto: peligro para el medio ambiente, no una indicación directa de inflamabilidad o toxicidad aguda.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2780,"role":16,"source_file":"T62_FIG_16_P060.png","asset_id":152945,"manual_page":"504","correct_index":1,"stem":"Al identificar el pictograma CLP de dos tubos vertiendo líquido, ¿qué consecuencia y correspondencia con las clases de transporte describe el manual?","options":["Comburencia de materiales y asfixia por gases; el peligro comburente se identifica en ADR con clase 8.","Corrosión de materiales y lesiones en tejidos; el peligro corrosivo se identifica en ADR con clase 8.","Inflamación espontánea por contacto con aire; el peligro se identifica en ADR con clase 6.1.","Toxicidad aguda por ingestión sin daño de superficies; el peligro se identifica en ADR con clase 4.3."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: Corrosión de materiales y lesiones en tejidos; el peligro corrosivo se identifica en ADR con clase 8.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2781,"role":17,"source_file":"T62_FIG_17_P060.png","asset_id":152946,"manual_page":"504","correct_index":2,"stem":"La imagen muestra un signo que también aparece en etiquetas de transporte. ¿Qué asociación entre su grafismo y la clasificación ADR es correcta?","options":["La llama sobre círculo caracteriza inflamabilidad de clase 4.1, distinta de la denominación de peróxidos de clase 5.1.","La llama sobre círculo caracteriza toxicidad de clase 6.1, distinta de la denominación de comburentes de clase 5.2.","La llama sobre círculo caracteriza comburencia de clase 5.1, distinta de la denominación de peróxidos orgánicos de clase 5.2.","La llama sobre círculo caracteriza reacción con agua de clase 4.3, distinta de la denominación de comburentes de clase 5.1."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: La llama sobre círculo caracteriza comburencia de clase 5.1, distinta de la denominación de peróxidos orgánicos de clase 5.2.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2782,"role":18,"source_file":"T62_FIG_18_P060.png","asset_id":152947,"manual_page":"504","correct_index":0,"stem":"La calavera se representa tanto en un sistema antiguo como en CLP. ¿Qué comparación de significados evita equipararla con la cruz de San Andrés?","options":["Calavera: toxicidad aguda; en la etiqueta antigua T se distingue de la cruz asignada a nocivo (Xn) o irritante (Xi).","Calavera: irritación leve; en la etiqueta antigua Xi se distingue de la cruz asignada a tóxico (T).","Calavera: peligro medioambiental; en la etiqueta antigua N se distingue de la cruz asignada a corrosivo (C).","Calavera: comburencia; en la etiqueta antigua O se distingue de la cruz asignada a inflamable (F)."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: Calavera: toxicidad aguda; en la etiqueta antigua T se distingue de la cruz asignada a nocivo (Xn) o irritante (Xi).","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2783,"role":19,"source_file":"T62_FIG_19_P060.png","asset_id":152948,"manual_page":"504","correct_index":3,"stem":"En la familia de riesgos CLP, ¿qué combinación permite distinguir el pictograma de silueta torácica del signo de exclamación y la calavera?","options":["La silueta alerta de toxicidad aguda; la exclamación se usa para corrosión y la calavera para peligros ambientales.","La silueta alerta de inflamación; la exclamación se usa para gases presurizados y la calavera para toxicidad crónica.","La silueta alerta de combustión espontánea; la exclamación se usa para oxidantes y la calavera para irritación.","La silueta alerta de peligros graves para la salud; la exclamación se usa para irritación/nocividad y la calavera para toxicidad aguda."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: La silueta alerta de peligros graves para la salud; la exclamación se usa para irritación/nocividad y la calavera para toxicidad aguda.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2784,"role":20,"source_file":"T62_FIG_20_P023.png","asset_id":152949,"manual_page":"467","correct_index":1,"stem":"Para la etiqueta radiactiva II amarilla representada, ¿qué combinación de índice de transporte y tasa superficial se ajusta a los límites de la tabla 20?","options":["Índice de transporte mayor que 1 e inferior a 10, con tasa en superficie mayor de 0,5 e inferior a 2 mSv/h.","Índice de transporte mayor que 0 e inferior a 1, con tasa en superficie mayor de 0,005 e inferior a 0,5 mSv/h.","Índice de transporte inferior a 0,05, con tasa en superficie de hasta 0,005 mSv/h.","Índice de transporte mayor de 10, con tasa en superficie mayor de 2 e inferior a 10 mSv/h."],"explanation":"CEIS NRBQ, página impresa 467. La correspondencia correcta es: Índice de transporte mayor que 0 e inferior a 1, con tasa en superficie mayor de 0,005 e inferior a 0,5 mSv/h.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2785,"role":21,"source_file":"T62_FIG_21_P024.png","asset_id":152950,"manual_page":"468","correct_index":2,"stem":"La señal ADR con barras superiores y cifra 9 debe interpretarse conjuntamente con los ejemplos que da el manual. ¿Qué asociación es íntegramente correcta?","options":["Clase 8: materias y objetos corrosivos, como amianto, pilas de litio o aparatos de salvamento.","Clase 6.2: materias y objetos infecciosos, como amianto, pilas de litio o aparatos de salvamento.","Clase 9: mercancías y objetos diversos, como amianto, pilas de litio o aparatos de salvamento.","Clase 7: materias y objetos radiactivos, como amianto, pilas de litio o aparatos de salvamento."],"explanation":"CEIS NRBQ, página impresa 468. La correspondencia correcta es: Clase 9: mercancías y objetos diversos, como amianto, pilas de litio o aparatos de salvamento.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2786,"role":22,"source_file":"T62_FIG_22_P022.png","asset_id":152951,"manual_page":"466","correct_index":0,"stem":"Al comparar esta marca biológica con la etiqueta de calavera, ¿qué correspondencia entre división ADR y muestras o residuos representa correctamente el manual?","options":["Clase 6.2: materias infecciosas, incluidas determinadas muestras de diagnóstico y residuos clínicos.","Clase 6.1: materias infecciosas, incluidas determinadas muestras de diagnóstico y residuos clínicos.","Clase 6.2: materias tóxicas definidas exclusivamente por los límites de DL50 de la tabla 17.","Clase 6.1: gases asfixiantes y productos corrosivos, incluidos como muestras de diagnóstico."],"explanation":"CEIS NRBQ, página impresa 466. La correspondencia correcta es: Clase 6.2: materias infecciosas, incluidas determinadas muestras de diagnóstico y residuos clínicos.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2787,"role":23,"source_file":"T62_FIG_23_P019.png","asset_id":152952,"manual_page":"463","correct_index":3,"stem":"El signo antiguo con dos probetas se encuentra entre los pictogramas de residuos. ¿Qué pareja de código y descripción diferencia este peligro de la toxicidad marcada con T?","options":["Código T: corrosivo, capaz de atacar materiales y provocar lesiones por contacto; C corresponde a toxicidad.","Código O: corrosivo, capaz de atacar materiales y provocar lesiones por contacto; T corresponde a inflamabilidad.","Código Xi: corrosivo, capaz de atacar materiales y provocar lesiones por contacto; C corresponde a comburencia.","Código C: corrosivo, capaz de atacar materiales y provocar lesiones por contacto; T corresponde a toxicidad."],"explanation":"CEIS NRBQ, página impresa 463. La correspondencia correcta es: Código C: corrosivo, capaz de atacar materiales y provocar lesiones por contacto; T corresponde a toxicidad.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2788,"role":24,"source_file":"T62_FIG_24_P019.png","asset_id":152953,"manual_page":"463","correct_index":1,"stem":"Al cotejar el símbolo antiguo de calavera con el de cruz de San Andrés, ¿qué asociación de letras y peligros corresponde a la clasificación de residuos?","options":["Calavera Xn: tóxico; cruz T: nocivo y cruz Xi: irritante, sin cambiar el símbolo de las dos últimas.","Calavera T: tóxico; cruz Xn: nocivo y cruz Xi: irritante, sin cambiar el símbolo de las dos últimas.","Calavera T: irritante; cruz Xn: tóxico y cruz Xi: nocivo, sin cambiar el símbolo de las dos últimas.","Calavera C: corrosivo; cruz Xn: nocivo y cruz F: inflamable, sin cambiar el símbolo de las dos últimas."],"explanation":"CEIS NRBQ, página impresa 463. La correspondencia correcta es: Calavera T: tóxico; cruz Xn: nocivo y cruz Xi: irritante, sin cambiar el símbolo de las dos últimas.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2789,"role":25,"source_file":"T62_FIG_25_P019.png","asset_id":152954,"manual_page":"463","correct_index":2,"stem":"Ante dos recipientes con la cruz negra del sistema antiguo, ¿qué información adicional permite distinguir correctamente nocividad e irritación según el texto?","options":["El código Xi indica nocivo y Xn irritante; el pictograma común no basta para diferenciarlos.","El código Xn indica tóxico y T irritante; el pictograma común no basta para diferenciarlos.","El código Xn indica nocivo y Xi irritante; el pictograma común no basta para diferenciarlos.","El código F indica nocivo y Xi comburente; el pictograma común no basta para diferenciarlos."],"explanation":"CEIS NRBQ, página impresa 463. La correspondencia correcta es: El código Xn indica nocivo y Xi irritante; el pictograma común no basta para diferenciarlos.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2790,"role":26,"source_file":"T62_FIG_26_P019.png","asset_id":152955,"manual_page":"463","correct_index":0,"stem":"La imagen corresponde a la señalización antigua de un residuo. ¿Qué asociación de letra, grafismo y riesgo evita confundirla con una llama del mismo sistema?","options":["Letra E, bomba explosionando y riesgo explosivo; F corresponde a la llama inflamable.","Letra F, bomba explosionando y riesgo explosivo; E corresponde a la llama inflamable.","Letra O, bomba explosionando y riesgo explosivo; C corresponde a la llama inflamable.","Letra T, bomba explosionando y riesgo explosivo; Xn corresponde a la llama inflamable."],"explanation":"CEIS NRBQ, página impresa 463. La correspondencia correcta es: Letra E, bomba explosionando y riesgo explosivo; F corresponde a la llama inflamable.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2791,"role":27,"source_file":"T62_FIG_27_P019.png","asset_id":152956,"manual_page":"463","correct_index":3,"stem":"La llama del antiguo sistema de residuos no basta para fijar el grado de inflamabilidad. ¿Qué diferencia entre los códigos F, F+ y O recoge el manual?","options":["F identifica comburencia; F+ identifica corrosión intensa; O corresponde a inflamabilidad con llama sobre círculo.","F identifica inflamabilidad; F+ identifica toxicidad aguda; O corresponde a combustión espontánea con llama sola.","F identifica fácil inflamabilidad; F+ identifica explosividad; O corresponde a irritación con cruz de San Andrés.","F identifica inflamabilidad; F+ identifica fácil o extrema inflamabilidad; O corresponde a comburencia con llama sobre círculo."],"explanation":"CEIS NRBQ, página impresa 463. La correspondencia correcta es: F identifica inflamabilidad; F+ identifica fácil o extrema inflamabilidad; O corresponde a comburencia con llama sobre círculo.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2792,"role":28,"source_file":"T62_FIG_28_P019.png","asset_id":152957,"manual_page":"463","correct_index":1,"stem":"La llama sobre un círculo de la imagen pertenece al sistema antiguo. ¿Qué combinación de código y riesgo la distingue de una llama aislada?","options":["F: comburente y llama sobre círculo; O: inflamable y llama aislada, aunque ambas se relacionen con incendios.","O: comburente y llama sobre círculo; F: inflamable y llama aislada, aunque ambas se relacionen con incendios.","O: peróxido orgánico y llama aislada; E: comburente y llama sobre círculo, aunque ambas provoquen incendios.","C: corrosivo y llama sobre círculo; F+: comburente y llama aislada, aunque ambas provoquen incendios."],"explanation":"CEIS NRBQ, página impresa 463. La correspondencia correcta es: O: comburente y llama sobre círculo; F: inflamable y llama aislada, aunque ambas se relacionen con incendios.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2793,"role":29,"source_file":"T62_FIG_29_P060.png","asset_id":152958,"manual_page":"504","correct_index":2,"stem":"El símbolo antiguo de árbol y pez se compara con los pictogramas CLP y los rombos ADR del manual. ¿Cuál es la relación de riesgos correcta?","options":["El árbol y pez del sistema antiguo expresa inflamabilidad; en CLP existe una señal análoga con borde rojo.","El árbol y pez del sistema antiguo expresa toxicidad aguda; en CLP equivale a calavera con borde rojo.","El árbol y pez del sistema antiguo expresa peligro medioambiental; en CLP existe una señal análoga con borde rojo.","El árbol y pez del sistema antiguo expresa radiación ionizante; en ADR equivale a la etiqueta de clase 7."],"explanation":"CEIS NRBQ, página impresa 504. La correspondencia correcta es: El árbol y pez del sistema antiguo expresa peligro medioambiental; en CLP existe una señal análoga con borde rojo.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2794,"role":30,"source_file":"T62_FIG_30_P057.png","asset_id":152959,"manual_page":"501","correct_index":0,"stem":"Sitúe visualmente el campo «código de acción» del panel Hazchem. Si se indicase 3P, ¿qué combinación de extinción, protección y medidas se deduce del apartado del manual?","options":["El 3 admite espuma o agente seco, no niebla ni chorro pleno; P exige protección completa y medidas de dilución sujetas a seguridad ambiental.","El 3 admite niebla o espuma, no agente seco; P exige solo uniforme ordinario y prohíbe diluir bajo cualquier condición.","El 3 admite chorro pleno o niebla, no espuma; P exige protección completa, pero obliga a verter el producto al alcantarillado.","El 3 admite espuma o agente seco, no agua; P permite actuar sin equipo respiratorio y descarta precauciones por reacción violenta."],"explanation":"CEIS NRBQ, página impresa 501. La correspondencia correcta es: El 3 admite espuma o agente seco, no niebla ni chorro pleno; P exige protección completa y medidas de dilución sujetas a seguridad ambiental.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2795,"role":31,"source_file":"T62_FIG_31_P057.png","asset_id":152960,"manual_page":"501","correct_index":3,"stem":"Al interpretar el rombo NFPA representado, ¿qué correspondencia entre posiciones, escalas y casilla especial respeta el manual?","options":["Azul reactividad, rojo inflamabilidad, amarillo salud: cada uno escala 0–4; blanco informa riesgos especiales.","Azul salud, rojo reactividad, amarillo inflamabilidad: cada uno escala 1–5; blanco informa riesgos especiales.","Azul salud, rojo inflamabilidad, amarillo reactividad: cada uno escala 0–4; blanco indica exclusivamente concentración.","Azul salud, rojo inflamabilidad, amarillo reactividad: cada uno escala 0–4; blanco informa riesgos especiales."],"explanation":"CEIS NRBQ, página impresa 501. La correspondencia correcta es: Azul salud, rojo inflamabilidad, amarillo reactividad: cada uno escala 0–4; blanco informa riesgos especiales.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2796,"role":32,"source_file":"T62_FIG_32_P056.png","asset_id":152961,"manual_page":"500","correct_index":1,"stem":"En las dos marcas de cantidades limitadas, ¿qué requisito dimensional y qué condición permiten reducir su tamaño conforme al texto del manual?","options":["El rombo mide al menos 10 × 10 cm, con borde mínimo de 5 mm; puede reducirse a 5 × 5 cm si el bulto lo exige y sigue legible.","El rombo mide al menos 10 × 10 cm, con borde mínimo de 2 mm; puede reducirse a 5 × 5 cm si el bulto lo exige y sigue legible.","El rombo mide al menos 25 × 25 cm, con borde mínimo de 2 mm; puede reducirse a 10 × 10 cm si el bulto lo exige y sigue legible.","El rombo mide al menos 10 × 10 cm, con borde mínimo de 2 mm; puede reducirse a 2 × 2 cm aunque deje de ser visible."],"explanation":"CEIS NRBQ, página impresa 500. La correspondencia correcta es: El rombo mide al menos 10 × 10 cm, con borde mínimo de 2 mm; puede reducirse a 5 × 5 cm si el bulto lo exige y sigue legible.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2797,"role":33,"source_file":"T62_FIG_33_P056.png","asset_id":152962,"manual_page":"500","correct_index":2,"stem":"La marca de la imagen lleva una E y no debe confundirse con las figuras para cantidades limitadas. ¿Qué combinación de finalidad y tamaño se ajusta al manual?","options":["Identifica bultos con mercancías en cantidades limitadas; el manual establece una señal de 10 × 10 cm.","Identifica transportes de materias en caliente; el manual establece una señal triangular de 10 cm por lado.","Identifica bultos con mercancías en cantidades exceptuadas; el manual establece una señal de 10 × 10 cm.","Identifica una clase ADR de mercancías infecciosas; el manual establece una placa de 25 × 25 cm."],"explanation":"CEIS NRBQ, página impresa 500. La correspondencia correcta es: Identifica bultos con mercancías en cantidades exceptuadas; el manual establece una señal de 10 × 10 cm.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2798,"role":34,"source_file":"T62_FIG_34_P056.png","asset_id":152963,"manual_page":"500","correct_index":0,"stem":"Ante la marca triangular con termómetro, ¿qué disposición exige el manual al comparar vehículo y contenedor con mercancía en caliente?","options":["Marca roja de al menos 25 cm de lado: en vehículo, ambos laterales y trasera; en contenedores, los cuatro lados.","Marca roja de al menos 10 cm de lado: en vehículo, ambos laterales y trasera; en contenedores, los cuatro lados.","Marca roja de al menos 25 cm de lado: en vehículo, solo frontal y trasera; en contenedores, únicamente dos lados.","Marca amarilla de al menos 25 cm de lado: en vehículo, ambos laterales y trasera; en contenedores, los cuatro lados."],"explanation":"CEIS NRBQ, página impresa 500. La correspondencia correcta es: Marca roja de al menos 25 cm de lado: en vehículo, ambos laterales y trasera; en contenedores, los cuatro lados.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2799,"role":35,"source_file":"T62_FIG_35_P055.png","asset_id":152964,"manual_page":"499","correct_index":3,"stem":"La marca de árbol y pez en rombo blanco se refiere al transporte, no al pictograma CLP. Según el apartado correspondiente, ¿qué aplicación y excepción recogen las marcas de bultos?","options":["Señala materia corrosiva de clase 8, con marca de 10 × 10 cm salvo ajustes y excepción para envases inferiores a 5 L o 5 kg.","Señala materia peligrosa para el medio ambiente, con marca de 25 × 25 cm obligatoria incluso en envases inferiores a 5 L.","Señala exclusivamente líquido inflamable de clase 3, con marca de 10 × 10 cm obligatoria incluso en envases inferiores a 5 L.","Señala materia peligrosa para el medio ambiente, con marca de 10 × 10 cm salvo ajustes y excepción para envases inferiores a 5 L o 5 kg."],"explanation":"CEIS NRBQ, página impresa 499. La correspondencia correcta es: Señala materia peligrosa para el medio ambiente, con marca de 10 × 10 cm salvo ajustes y excepción para envases inferiores a 5 L o 5 kg.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2800,"role":36,"source_file":"T62_FIG_36_P053.png","asset_id":152965,"manual_page":"497","correct_index":1,"stem":"En el panel naranja se lee «33» encima de «1088». ¿Qué combinación de función, situación y longitud de los identificadores es correcta?","options":["33 es número ONU de la materia, arriba; 1088 es número de identificación del peligro de cuatro cifras, abajo.","33 es número de identificación del peligro, arriba; 1088 es número ONU de cuatro cifras que identifica la materia, abajo.","33 es código de acción Hazchem, arriba; 1088 es clase ADR de cuatro cifras, abajo.","33 es número de emergencia del vehículo, arriba; 1088 es código de inflamabilidad de cuatro cifras, abajo."],"explanation":"CEIS NRBQ, página impresa 497. La correspondencia correcta es: 33 es número de identificación del peligro, arriba; 1088 es número ONU de cuatro cifras que identifica la materia, abajo.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2801,"role":37,"source_file":"T62_FIG_37_P031.png","asset_id":152966,"manual_page":"475","correct_index":2,"stem":"La forma de sección de cisterna mostrada se compara con la ovalada. ¿Qué asociación de presión, capacidad longitudinal y resistencia lateral corresponde a la sección de la figura?","options":["Policéntrica: presión interior elevada y máxima carga con más longitud en uso urbano, con laterales más resistentes.","Ovalada: poca presión interior y máxima carga con menos longitud en uso urbano, con laterales menos resistentes.","Policéntrica: poca presión interior y máxima carga con menos longitud en uso urbano, con laterales menos resistentes.","Circular esférica: poca presión interior y máxima carga con menos longitud en uso urbano, con laterales menos resistentes."],"explanation":"CEIS NRBQ, página impresa 475. La correspondencia correcta es: Policéntrica: poca presión interior y máxima carga con menos longitud en uso urbano, con laterales menos resistentes.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2802,"role":38,"source_file":"T62_FIG_38_P031.png","asset_id":152967,"manual_page":"475","correct_index":0,"stem":"Al distinguir la sección de cisterna ovalada de la policéntrica en la tabla 24, ¿qué relación entre capacidad, longitud y costados corresponde a la imagen?","options":["Ovalada: poca presión interior, mayor longitud para igual capacidad y costados más resistentes que la policéntrica.","Ovalada: alta presión interior, menor longitud para igual capacidad y costados menos resistentes que la policéntrica.","Policéntrica: poca presión interior, mayor longitud para igual capacidad y costados más resistentes que la ovalada.","Circular esférica: poca presión interior, mayor longitud para igual capacidad y costados más resistentes que la ovalada."],"explanation":"CEIS NRBQ, página impresa 475. La correspondencia correcta es: Ovalada: poca presión interior, mayor longitud para igual capacidad y costados más resistentes que la policéntrica.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2803,"role":39,"source_file":"T62_FIG_39_P031.png","asset_id":152968,"manual_page":"475","correct_index":3,"stem":"Dentro de las secciones circulares de la tabla 24, ¿qué combinación de forma, mercancía y comportamiento atribuye el manual a la representada?","options":["Fondo esférico: mercancías peligrosas muy peligrosas y presión interior necesariamente baja, con costados poco resistentes.","Fondo semiesférico: solo granulados no peligrosos y uso prioritariamente urbano, con costados poco resistentes.","Fondo policéntrico: mercancías peligrosas muy peligrosas y presión interior elevada, con costados resistentes.","Fondo semiesférico: mercancías peligrosas muy peligrosas y buen comportamiento en accidentes, con costados resistentes."],"explanation":"CEIS NRBQ, página impresa 475. La correspondencia correcta es: Fondo semiesférico: mercancías peligrosas muy peligrosas y buen comportamiento en accidentes, con costados resistentes.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2804,"role":40,"source_file":"T62_FIG_40_P031.png","asset_id":152969,"manual_page":"475","correct_index":1,"stem":"La imagen de fondo esférico se diferencia del fondo semiesférico y del ovalado. ¿Qué característica justifica su selección en la tabla 24?","options":["Fondo esférico: poca presión interior, capacidad máxima en el menor largo y costados poco resistentes.","Fondo esférico: presión interior alta, comportamiento favorable ante accidentes y costados resistentes.","Fondo semiesférico: presión interior alta, diseño limitado a granulados y costados poco resistentes.","Fondo ovalado: presión interior alta, comportamiento inferior ante accidentes y costados resistentes."],"explanation":"CEIS NRBQ, página impresa 475. La correspondencia correcta es: Fondo esférico: presión interior alta, comportamiento favorable ante accidentes y costados resistentes.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2805,"role":41,"source_file":"T62_FIG_41_P024.png","asset_id":152970,"manual_page":"468","correct_index":2,"stem":"El rombo ADR de clase 9 representado comprende peligros diversos. ¿Qué grupo de ejemplos y comparación con otras clases ofrece el manual?","options":["Clase 9: incluye, entre otros, amianto, pilas de litio y aparatos de salvamento, todos clasificados como corrosivos de clase 8.","Clase 9: incluye, entre otros, material infeccioso, gases tóxicos y explosivos, sin diferencias con las clases 6.2 y 1.","Clase 9: incluye, entre otros, amianto, pilas de litio y aparatos de salvamento, no exclusivamente corrosivos de clase 8.","Clase 9: incluye únicamente los peróxidos orgánicos sometidos a control térmico, como una variante de la clase 5.2."],"explanation":"CEIS NRBQ, página impresa 468. La correspondencia correcta es: Clase 9: incluye, entre otros, amianto, pilas de litio y aparatos de salvamento, no exclusivamente corrosivos de clase 8.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2806,"role":42,"source_file":"T62_FIG_42_P024.png","asset_id":152971,"manual_page":"468","correct_index":0,"stem":"La etiqueta de transporte con cifra 8 remite a un tipo de riesgo que el texto subdivide por gravedad. ¿Qué clasificación y rasgo material corresponden?","options":["Clase 8: materias corrosivas, con grupos de embalaje I, II y III; el manual señala el daño de bases a tejidos.","Clase 8: materias tóxicas, con grupos de embalaje I, II y III; el manual señala el daño de bases a tejidos.","Clase 8: materias inflamables, sin grupos de embalaje; el manual señala el daño de bases a tejidos.","Clase 6.2: materias corrosivas, con grupos de embalaje I, II y III; el manual señala exclusivamente ácidos."],"explanation":"CEIS NRBQ, página impresa 468. La correspondencia correcta es: Clase 8: materias corrosivas, con grupos de embalaje I, II y III; el manual señala el daño de bases a tejidos.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2807,"role":43,"source_file":"T62_FIG_43_P022.png","asset_id":152972,"manual_page":"466","correct_index":3,"stem":"Al identificar la calavera en una etiqueta de transporte con cifra 6, ¿qué código de división y qué familia de riesgos secundarios recoge el texto?","options":["División 6.2, materias infecciosas; las combinaciones TF, TC y TO añaden inflamabilidad, corrosividad o comburencia.","División 6.1, materias corrosivas; las combinaciones TF, TC y TO añaden inflamabilidad, explosividad o radioactividad.","División 6.2, materias tóxicas; las combinaciones TF, TC y TO añaden infección, corrosividad o radiación.","División 6.1, materias tóxicas; las combinaciones TF, TC y TO añaden inflamabilidad, corrosividad o comburencia."],"explanation":"CEIS NRBQ, página impresa 466. La correspondencia correcta es: División 6.1, materias tóxicas; las combinaciones TF, TC y TO añaden inflamabilidad, corrosividad o comburencia.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2808,"role":44,"source_file":"T62_FIG_44_P022.png","asset_id":152973,"manual_page":"466","correct_index":1,"stem":"Las dos variantes de la clase general 6 se reconocen por sus símbolos. ¿Qué pareja de mecanismo y mercancía diferencia correctamente ambas subdivisiones?","options":["Símbolo biológico: 6.1, materias infecciosas como muestras diagnósticas; calavera: 6.2, materias tóxicas por distintas vías.","Símbolo biológico: 6.2, materias infecciosas como muestras diagnósticas; calavera: 6.1, materias tóxicas por distintas vías.","Símbolo biológico: 6.2, materias exclusivamente corrosivas; calavera: 6.1, materias infecciosas por contacto.","Símbolo biológico: 6.1, materias tóxicas sin agentes patógenos; calavera: 6.2, materias inflamables y autorreactivas."],"explanation":"CEIS NRBQ, página impresa 466. La correspondencia correcta es: Símbolo biológico: 6.2, materias infecciosas como muestras diagnósticas; calavera: 6.1, materias tóxicas por distintas vías.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2809,"role":45,"source_file":"T62_FIG_45_P021.png","asset_id":152974,"manual_page":"465","correct_index":2,"stem":"Para la subdivisión de clase 4 marcada en azul, ¿qué consecuencia operativa se extrae del mecanismo de riesgo indicado en el manual?","options":["La clase 4.2 puede liberar gases inflamables con aire; el manual excluye usar espuma, pero recomienda agua para diluir.","La clase 4.3 puede inflamarse espontáneamente en aire; el manual excluye usar polvo seco, pero recomienda agua para diluir.","La clase 4.3 puede liberar gases inflamables con agua; el manual excluye usarla como extintor o para diluir la materia.","La clase 4.1 puede liberar gases tóxicos con agua; el manual excluye solo el chorro pleno, pero permite la dilución."],"explanation":"CEIS NRBQ, página impresa 465. La correspondencia correcta es: La clase 4.3 puede liberar gases inflamables con agua; el manual excluye usarla como extintor o para diluir la materia.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2810,"role":46,"source_file":"T62_FIG_46_P021.png","asset_id":152975,"manual_page":"465","correct_index":0,"stem":"Al observar el pictograma de llama sobre círculo y su cifra, ¿qué clase y qué riesgos adicionales reconoce el manual a sus materias?","options":["División 5.1, materias comburentes; pueden ocasionar incendios o explosiones y también resultar tóxicas o corrosivas.","División 5.2, materias comburentes; pueden ocasionar incendios o explosiones y también resultar tóxicas o corrosivas.","División 5.1, gases inflamables; pueden ocasionar incendios o explosiones, pero nunca resultar tóxicos o corrosivos.","División 4.3, materias comburentes; al contacto con aire son necesariamente explosivas y carecen de riesgos añadidos."],"explanation":"CEIS NRBQ, página impresa 465. La correspondencia correcta es: División 5.1, materias comburentes; pueden ocasionar incendios o explosiones y también resultar tóxicas o corrosivas.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2811,"role":47,"source_file":"T62_FIG_47_P021.png","asset_id":152976,"manual_page":"465","correct_index":3,"stem":"El rombo rayado rojo y blanco es diferente del dividido en mitades. ¿Qué combinación de clase y familias de materias reproduce su clasificación?","options":["División 4.2: sólidos inflamables, autorreactivos y sólidos explosivos desensibilizados, frente a la inflamación espontánea de 4.1.","División 4.1: materias que liberan gas inflamable con agua, frente a la inflamación espontánea de 4.3.","División 4.3: sólidos inflamables, autorreactivos y sólidos explosivos desensibilizados, frente a la inflamación espontánea de 5.2.","División 4.1: sólidos inflamables, autorreactivos y sólidos explosivos desensibilizados, frente a la inflamación espontánea de 4.2."],"explanation":"CEIS NRBQ, página impresa 465. La correspondencia correcta es: División 4.1: sólidos inflamables, autorreactivos y sólidos explosivos desensibilizados, frente a la inflamación espontánea de 4.2.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2812,"role":48,"source_file":"T62_FIG_48_P021.png","asset_id":152977,"manual_page":"465","correct_index":1,"stem":"La señal bicolor de clase 4 exige distinguir el riesgo principal de un eventual riesgo subsidiario. ¿Qué enunciado se ajusta al texto?","options":["División 4.3: puede inflamarse o calentarse espontáneamente en aire; algunas materias además desprenden gases inflamables al mojarse.","División 4.2: puede inflamarse o calentarse espontáneamente en aire; algunas materias además desprenden gases inflamables al mojarse.","División 4.1: puede inflamarse o calentarse espontáneamente en aire; todas las materias son necesariamente corrosivas.","División 5.1: puede inflamarse o calentarse espontáneamente en aire; ninguna materia puede reaccionar con agua."],"explanation":"CEIS NRBQ, página impresa 465. La correspondencia correcta es: División 4.2: puede inflamarse o calentarse espontáneamente en aire; algunas materias además desprenden gases inflamables al mojarse.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2813,"role":49,"source_file":"T62_FIG_49_P021.png","asset_id":152978,"manual_page":"465","correct_index":2,"stem":"La etiqueta roja y amarilla lleva cifra 5.2. ¿Qué asociación entre naturaleza química y criterio de temperatura corresponde a lo descrito?","options":["Materias comburentes sin enlace O–O; P2 requiere regulación de temperatura, mientras que P1 no la requiere.","Peróxidos orgánicos con enlace O–O; P1 requiere regulación de temperatura, mientras que P2 no la requiere.","Peróxidos orgánicos con enlace O–O; P2 requiere regulación de temperatura, mientras que P1 no la requiere.","Sólidos inflamables con enlace O–O; P1 y P2 dependen solo de la presión del transporte."],"explanation":"CEIS NRBQ, página impresa 465. La correspondencia correcta es: Peróxidos orgánicos con enlace O–O; P2 requiere regulación de temperatura, mientras que P1 no la requiere.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2814,"role":50,"source_file":"T62_FIG_50_P020.png","asset_id":152979,"manual_page":"464","correct_index":0,"stem":"La etiqueta roja con cifra 3 debe relacionarse con los criterios del manual, que incluyen un supuesto distinto del líquido a temperatura ordinaria. ¿Cuál es correcto?","options":["Clase 3: líquidos con punto de inflamación ≤60 °C y determinados sólidos fundidos transportados por encima de su punto de inflamación.","Clase 3: líquidos con punto de inflamación >60 °C y determinados sólidos fundidos transportados por debajo de su punto de inflamación.","Clase 2: líquidos con punto de inflamación ≤60 °C y determinados sólidos fundidos transportados por encima de su punto de inflamación.","Clase 3: solamente líquidos con punto de inflamación ≤23 °C, sin admitir sólidos fundidos ni otras materias."],"explanation":"CEIS NRBQ, página impresa 464. La correspondencia correcta es: Clase 3: líquidos con punto de inflamación ≤60 °C y determinados sólidos fundidos transportados por encima de su punto de inflamación.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2815,"role":51,"source_file":"T62_FIG_51_P020.png","asset_id":152980,"manual_page":"464","correct_index":3,"stem":"Las etiquetas rojas de clase 2 comparten el símbolo de llama con otras clases. ¿Qué combinación de clase y codificación de peligros de los gases es correcta?","options":["Clase 3, gases inflamables; F identifica inflamabilidad y TF combina toxicidad e inflamabilidad.","Clase 2, gases no inflamables; F identifica corrosividad y TF combina toxicidad y comburencia.","Clase 4.1, gases inflamables; F identifica toxicidad y TF combina inflamabilidad y corrosividad.","Clase 2, gases inflamables; F identifica inflamabilidad y TF combina toxicidad e inflamabilidad."],"explanation":"CEIS NRBQ, página impresa 464. La correspondencia correcta es: Clase 2, gases inflamables; F identifica inflamabilidad y TF combina toxicidad e inflamabilidad.","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."},{"id":2816,"role":52,"source_file":"T62_FIG_52_P020.png","asset_id":152981,"manual_page":"464","correct_index":1,"stem":"En la figura aparecen etiquetas verdes y una blanca de clase 2. ¿Qué correspondencia de división y peligro distingue las tres variantes frente a la roja?","options":["Verde: gas inflamable (2.1); blanca con calavera: gas no tóxico (2.2); roja con llama: gas tóxico (2.3).","Verde: gas no inflamable/no tóxico (2.2); blanca con calavera: gas tóxico (2.3); roja con llama: gas inflamable (2.1).","Verde: gas no inflamable/no tóxico (2.2); blanca con calavera: gas inflamable (2.1); roja con llama: gas tóxico (2.3).","Verde: gas tóxico (2.3); blanca con calavera: gas inflamable (2.1); roja con llama: gas no inflamable (2.2)."],"explanation":"CEIS NRBQ, página impresa 464. La correspondencia correcta es: Verde: gas no inflamable/no tóxico (2.2); blanca con calavera: gas tóxico (2.3); roja con llama: gas inflamable (2.1).","verification_note":"Combinación documental de imagen seleccionada y clasificación/criterio de las páginas citadas."}],"does_not_change":["t62_nrbq_data.js","any PDF","coverage_items","graphic_assets","graphic image base64","calculators","test_sessions","SRS"],"policy":"52/52 user-selected images and source graphic asset retained; stronger four-option 2023/2024/2026 exam style, PDF only."};
